            border: 1px solid black;
            padding: 0.1in;
            text-align: left;
        }

        th {
            background: #e0e0e0;
        }

        .signature {
            width: 4in;
            height: 0.75in;
            border: 1px solid black;
            margin: 0.5in auto;
            position: relative;
        }

        .signature::after {
            content: "Signature";
            position: absolute;
            bottom: 0.1in;
            left: 0.2in;
            font-size: 10pt;
            color: #666;
        }

        .center {
            text-align: center;
        }

        .italic {
            font-style: italic;
        }

        /* Column layout simulation for multi-column documents */
        .columns {
            display: flex;
            gap: 0.5in;
        }

        .column {
            flex: 1;
        }

        @media print {
            body {
                margin: 0;
                max-width: none;
            }
        }
    </style>
</head>
